      return { kind: "blocked", reason: "it is a directory" };
    } else if (!st.isFile()) {
      return { kind: "skip", reason: "not a regular file" };
    } else {
      return { kind: "file", key, path, size: st.size };
    }
  }
  return { kind: "missing" };
