  hash: (file: LocalFile) => Promise<string>;
  /** Passes each distinct warning on to the caller's reporter, once. */
  warn: Reporter;
  /** The warnings passed on so far: one per entry skipped on either side. */
  warnings: Set<string>;
}

/**
