    upload: pushPlan.upload.map(({ key }) => ({ key, why: remoteKeys.has(key) ? "differs" : "missing" })),
    download: pullPlan.download.map(({ blob: { key } }) => ({ key, why: localKeys.has(key) ? "differs" : "missing" })),
