  child.stdout.setEncoding("utf8").on("data", (c: string) => (stdout += c));
  child.stderr.setEncoding("utf8").on("data", (c: string) => (stderr += c));
  return once(child, "exit").then(([code]) => ({ code: code as number | null, stdout, stderr }));
