 * into place, so it is never left half-written. A blob that can't be
 * downloaded or written doesn't stop the others: it ends up in the
 * summary's `failed`.
 */
export async function pull(dir: string, client: SyncboxClient, reporter: Reporter): Promise<PullSummary> {
  await assertDirectory(dir);
  const plan = await planPull(dir, await client.list(), reporter);

  const downloaded: string[] = [];
  const { failed, notAttempted } = await transferEach(
    plan.download,
    ({ blob }) => blob.key,
    async ({ blob, target }) => {
      await download(client, blob, target);
      downloaded.push(blob.key);
      reporter.info(`downloaded ${blob.key}`);
    },
  );
  return {
    downloaded,
    unchanged: plan.unchanged,
    skipped: plan.skipped,
    failed: [...plan.failed, ...plan.blocked.map(blockedFailure), ...failed].sort(byKey),
    notAttempted,
  };
}

export function blockedFailure({ key, reason }: { key: string; reason: string }): Failure {
  return { key, message: `cannot write ${key}: ${reason}` };
}

