    info: (line) => reporter.info(line),
    warn: (line) => {
      if (warnings.has(line)) return;
      warnings.add(line);
      reporter.warn(line);
    },
  };

  const push = await planPush(dir, remote, warn, hash);
  const pull = await planPull(dir, remote, warn, hash);
  return { push, pull, hash, warn, warnings };
